    <div style={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 4 }}>
      <FormLabel id="tab-navigation-radio-buttons-group-label">
        Tab Navigation
      </FormLabel>
      <FormControl component="fieldset">
        <RadioGroup
          row
          value={tabNavigation}
          onChange={(event) => setTabNavigation(event.target.value)}
          name="grid-tab-navigation"
          aria-labelledby="tab-navigation-radio-buttons-group-label"
        >
          <FormControlLabel
            value="none"
            control={<Radio />}
            label={<code>&quot;none&quot;</code>}
          />
          <FormControlLabel
            value="content"
            control={<Radio />}
            label={<code>&quot;content&quot;</code>}
          />
          <FormControlLabel
            value="header"
            control={<Radio />}
            label={<code>&quot;header&quot;</code>}
          />
          <FormControlLabel
            value="all"
            control={<Radio />}
            label={<code>&quot;all&quot;</code>}
          />
        </RadioGroup>
      </FormControl>

      {/* Top tab barrier */}
      <div
        role="button"
        tabIndex={0}
        onKeyDown={preventKeyDown('Tab', true)}
        onBlur={resetKeyPressCount}
        style={{
          width: '100%',
          padding: '8px',
          textAlign: 'center',
          fontSize: '12px',
        }}
      >
        Tab Barrier (prevents Shift+Tab 3 times)
      </div>

      <Box style={{ height: 500, width: '100%' }}>
        <DataGridPro
          rows={rows}
          columns={columns}
          columnGroupingModel={columnGroupingModel}
          tabNavigation={tabNavigation}
          headerFilters
        />
      </Box>

      {/* Bottom tab barrier */}
      <div
        role="button"
        tabIndex={0}
        onKeyDown={preventKeyDown('Tab', false)}
        onBlur={resetKeyPressCount}
        style={{
          width: '100%',
          padding: '8px',
          textAlign: 'center',
          fontSize: '12px',
        }}
      >
        Tab Barrier (prevents Tab 3 times)
      </div>
    </div>
  );
}
